import sys
import xml.etree.ElementTree as ET
import re

def evaluate_expression(expr):
    try:
        return eval(expr, {'__builtins__': None}, {})
    except:
        return 0

def process_card(card):
    title = card.find('title').text
    body = card.find('body').text
    body = re.sub(r'\{\{(\d+[+\-*()\d]*)\}\}', lambda m: str(evaluate_expression(m.group(1))), body)
    return f'<article><h2>{title}</h2><p>{body}</p></article>'

