import sys
import xml.etree.ElementTree as ET
import re

def evaluate_expression(expr):
    try:
        return int(eval(expr))
    except:
        return 0

def render_cards(input_xml, output_html):
    tree = ET.parse(input_xml)
    root = tree.getroot()

    html_lines = ["<html><body>"]

    for card in root.findall('card'):
        title = card.find('title').text
        body = card.find('body').text

        # Replace placeholders with evaluated expressions
        def replace_placeholder(match):
            expr = match.group(1)
            return str(evaluate_expression(expr))

        body_processed = re.sub(r'\{\{([^}]+)\}\}', replace_placeholder, body)

        html_lines.append(f'<article><h2>{title}</h2><p>{body_processed}</p></article>')

    html_lines.append('</body></html>')
    with open(output_html, 'w') as f:
        f.write('\n'.join(html_lines))

    print(f"{len(root.findall('card'))} cards rendered")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python render_cards.py <input.xml> <output.html>")
        sys.exit(1)

    input_xml = sys.argv[1]
    output_html = sys.argv[2]
    render_cards(input_xml, output_html)
